<?php defined('BASEPATH') OR exit('No direct script access allowed'); include APPPATH . 'views/layouts/header.php'; include APPPATH . 'views/layouts/sidebar.php'; $mutable = $cycle->state === 'draft'; ?>
<div class="ami-panel"><div class="ami-panel-body"><div class="d-flex justify-content-between align-items-center flex-wrap mb-3"><h2 class="ami-section-title m-0"><?php echo html_escape($cycle->cycle_code . ' — ' . $cycle->title); ?></h2><?php if ($mutable): ?><span><a class="btn-ami btn-outline-ami" href="<?php echo site_url('lpmpi/spmi-audits/cycle/edit/' . (int) $cycle->id); ?>">Edit</a> <a class="btn-ami btn-outline-ami" href="<?php echo site_url('lpmpi/spmi-audits/assignment/create/' . (int) $cycle->id); ?>">Tambah penugasan</a></span><?php endif; ?></div><p>Periode: <?php echo html_escape($cycle->start_date . ' — ' . $cycle->end_date); ?> | Status: <strong><?php echo html_escape($cycle->state); ?></strong></p><?php if (!$mutable): ?><div class="alert alert-info">Siklus configured atau closed bersifat frozen dan hanya-baca. Snapshot M7 tidak berubah mengikuti sumber M3/M6.</div><?php else: ?><div class="alert alert-warning">Siklus draft: metadata dan penugasan masih dapat diubah.</div><?php endif; ?><p><?php echo nl2br(html_escape($cycle->description ?: 'Deskripsi belum diisi.')); ?></p><?php if ($mutable): ?><div class="mb-3"><?php foreach (['configured' => 'Tandai configured', 'closed' => 'Tutup siklus'] as $state => $label): ?><?php echo form_open('lpmpi/spmi-audits/cycle/transition/' . (int) $cycle->id, ['class' => 'd-inline']); ?><input type="hidden" name="state" value="<?php echo html_escape($state); ?>"><button class="btn-ami btn-sm btn-outline-ami" type="submit"><?php echo html_escape($label); ?></button></form> <?php endforeach; ?></div><?php elseif ($cycle->state === 'configured'): ?><?php echo form_open('lpmpi/spmi-audits/cycle/transition/' . (int) $cycle->id, ['class' => 'mb-3']); ?><input type="hidden" name="state" value="draft"><button class="btn-ami btn-sm btn-outline-ami" type="submit">Kembalikan ke draft</button></form><?php endif; ?><h3 class="ami-section-title mt-4">Penugasan snapshot</h3><?php if (empty($assignments)): ?><div class="ami-empty"><div class="ami-empty-title">Belum ada penugasan</div><div>Lengkapi paket M6 dengan pertanyaan dan rubrik skor 1–4 sebelum membuat penugasan.</div></div><?php else: ?><div class="table-responsive"><table class="table ami-table"><thead><tr><th>Paket</th><th>Auditor</th><th>Auditee</th><th>Aksi</th></tr></thead><tbody><?php foreach ($assignments as $assignment): ?><tr><td><?php echo html_escape($assignment->source_package_code . ' — ' . $assignment->source_package_title); ?></td><td><?php echo html_escape($assignment->auditor_name . ' — ' . $assignment->auditor_email); ?></td><td><?php echo html_escape($assignment->auditee_name . ' — ' . $assignment->auditee_email); ?></td><td><a href="<?php echo site_url('lpmpi/spmi-audits/assignment/detail/' . (int) $assignment->id); ?>">Snapshot</a><?php if ($mutable): ?> <?php echo form_open('lpmpi/spmi-audits/assignment/delete/' . (int) $assignment->id, ['class' => 'd-inline']); ?><button class="btn btn-link p-0" type="submit">Hapus</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div>
